/**
 * GitHub Actions workflow that gates on requirement coverage.
 */

export function renderWorkflow(opts = {}) {
  const min = opts.min ?? 80;
  const failUncovered = opts.failUncovered !== false;

  const args = [`--min ${min}`];
  if (failUncovered) args.push('--fail-uncovered');

  return `# Requirement coverage gate.
#
# Generated by \`specgate init\`. Adjust the threshold below to match your
# project's current state, then raise it as coverage improves.

name: Requirement coverage

on:
  pull_request:
  push:
    branches: [main]

jobs:
  specgate:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: 20

      - name: Check requirement coverage
        run: npx specgate ${args.join(' ')}

      # Uncomment to surface gaps in GitHub code scanning.
      # - name: Write SARIF report
      #   run: npx specgate --sarif-out specgate.sarif --format sarif
      # - uses: github/codeql-action/upload-sarif@v3
      #   with:
      #     sarif_file: specgate.sarif
`;
}
